_label_cache = {}
_ancestor_cache = {}
CACHE_LIMIT = 200000


def labels_of(name):
    cached = _label_cache.get(name)
    if cached is None:
        cached = [] if name == '.' else name[:-1].split('.')
        _label_cache[name] = cached
    return cached


def suffix_name(labels, skip):
    """Name obtained by dropping the leading `skip` labels."""
    rest = labels[skip:]
    if not rest:
        return '.'
    return '.'.join(rest) + '.'


def parent_name(name):
    labels = labels_of(name)
    return suffix_name(labels, 1)


def ancestors_of(name):
    """`name` followed by every ancestor, ending at the root (shared tails)."""
    cached = _ancestor_cache.get(name)
    if cached is not None:
        return cached
    chain = []
    cursor = name
    while True:
        chain.append(cursor)
        known = _ancestor_cache.get(cursor)
        if known is not None:
            chain.extend(known[1:])
            break
        if cursor == '.':
            break
        cursor = parent_name(cursor)
    if len(_ancestor_cache) < CACHE_LIMIT:
        _ancestor_cache[name] = chain
    return chain


def at_or_below(owner_labels, origin_labels):
    extra = len(owner_labels) - len(origin_labels)
    if extra < 0:
        return False
    if not origin_labels:
        return True
    return owner_labels[extra:] == origin_labels


